/* ---------------- sharing it ----------------
   What the text will look like in a bio or a post, how it will be counted there, and the two fixes
   that matter most: line breaks that survive, and cutting it to length without chopping a word. */
function typeShare(sets, items) {
  const t = typeState;
  if (!t.shareText) t.shareText = t.text || 'SungFluence';
  SOCIAL.forEach((s) => {
    const row = el('div', 'set'); row.setAttribute('aria-current', String(t.where === s.id));
    const b = el('button', null, s.name); b.type = 'button'; b.onclick = () => { t.where = s.id; renderTypeBox(); };
    row.append(b, el('small', null, String(s.limit)));
    sets.appendChild(row);
  });
  sets.appendChild(el('span', 'note', 'The limits were taken from public guides in November 2026, not from the apps themselves. Treat them as a guide: apps change them.'));

  const place = SOCIAL.find((s) => s.id === t.where) || SOCIAL[0];
  const ta = el('textarea', 'field'); ta.rows = 5; ta.value = t.shareText; ta.dir = 'auto';
  ta.setAttribute('aria-label', 'The text to share');
  ta.oninput = () => { t.shareText = ta.value; drawShare(); refreshPreview(); };
  items.append(el('span', 'sec-t', place.name), ta);
  const box = el('div', 'share-box'); box.id = 'shareBox';
  items.appendChild(box);
  const row = el('div', 'row2');
  row.append(optBtn('Make the line breaks stick', () => { t.shareText = fixBreaks(t.shareText); renderTypeBox(); }),
    optBtn('Cut it to fit', () => { t.shareText = fitTo(t.shareText, place.limit, place.count); renderTypeBox(); }),
    optBtn('Take the styling off', () => { t.shareText = unstyleText(t.shareText); renderTypeBox(); }));
  items.appendChild(row);
  drawShare(box);
}
function drawShare(el2) {
  const t = typeState, box = el2 || document.getElementById('shareBox');
  if (!box) return;
  const place = SOCIAL.find((s) => s.id === t.where) || SOCIAL[0];
  const txt = t.shareText || '';
  const used = countFor(txt, place.count);
  const over = used - place.limit;
  box.replaceChildren();
  // what it will look like where it is going
  const card = el('div', 'share-card');
  if (place.kind !== 'name') {
    const head = el('div', 'share-head');
    head.append(el('span', 'share-pic'), el('span', 'share-name', 'your name'));
    card.appendChild(head);
  }
  const body = el('div', 'share-body' + (place.kind === 'name' ? ' one-line' : '')); body.dir = 'auto';
  const shown = over > 0 ? Array.from(txt).slice(0, place.limit).join('') : txt;
  if (place.cut && Array.from(shown).length > place.cut) {
    body.append(document.createTextNode(Array.from(shown).slice(0, place.cut).join('')));
    const more = el('span', 'share-more', '… more');
    body.append(more);
    const rest = el('div', 'share-rest', Array.from(shown).slice(place.cut).join(''));
    card.append(body, rest);
  } else { body.textContent = shown; card.appendChild(body); }
  if (over > 0) card.appendChild(el('div', 'share-cut', over + ' character' + (over === 1 ? '' : 's') + ' past the limit would be cut off'));
  box.appendChild(card);
  // the count, the way that app counts
  const bar = el('div', 'share-bar');
  const fill = el('i'); fill.style.width = Math.min(100, used / place.limit * 100) + '%';
  if (over > 0) fill.classList.add('over');
  bar.appendChild(fill);
  const c = textCounts(txt);
  const line = el('div', 'type-count');
  line.append(el('span', over > 0 ? 'warn' : null, used + ' of ' + place.limit + (place.count === 'x' ? ', counted the way X counts' : ' characters')),
    el('span', null, c.letters + ' letters as people see them'), el('span', null, c.units + ' units'));
  box.append(bar, line);
  if (place.note) box.appendChild(el('div', 'note', place.note));
  if (place.breaks && txt.includes('\n')) {
    const ok2 = breaksWillStick(txt);
    box.appendChild(el('div', ok2 ? 'ok' : 'warn', ok2
      ? 'The line breaks here should survive: no line is empty and none ends in a space.'
      : 'Some lines are empty or end in a space, so the breaks may be dropped. Use the button below.'));
  }
  if (c.units !== c.letters) box.appendChild(el('span', 'note', 'Fancy letters take more room than they look: each one can count as two or more.'));
}

/* ---------------- keyword expansions ---------------- */
function typeExpand(sets, items) {
  sets.appendChild(el('span', 'note', 'Type (shrug) or :shrug: in any text box in SungFluence and it turns into the text you set here. The list is saved on this computer.'));
  const ex = el('div', 'row2');
  [['plain', 'Plain list'], ['espanso', 'Espanso'], ['ahk', 'AutoHotkey'], ['apple', 'Mac and iPhone']].forEach(([k, name]) => {
    ex.appendChild(optBtn(name, () => {
      const file = { plain: 'expansions.txt', espanso: 'sungfluence.yml', ahk: 'sungfluence.ahk', apple: 'expansions.plist' }[k];
      saveFile(file, expansionsAs(k));
    }));
  });
  sets.append(el('span', 'lab', 'Use them everywhere'), ex);
  sets.appendChild(el('span', 'note', 'Espanso works on Windows, Mac and Linux. AutoHotkey is for Windows. The Mac file goes to Settings, Keyboard, Text Replacements.'));

  items.appendChild(el('span', 'sec-t', 'Your expansions'));
  const tryIt = el('input', 'field'); tryIt.type = 'text'; tryIt.value = typeState.text; tryIt.setAttribute('aria-label', 'Try an expansion');
  tryIt.placeholder = 'Try it here: hello (shrug) and (heart)';
  tryIt.oninput = () => { typeState.text = tryIt.value; refreshPreview(); const o = document.getElementById('expOut'); if (o) o.textContent = expandText(tryIt.value); };
  items.append(tryIt, el('div', 'face-big', expandText(typeState.text)));
  items.lastChild.id = 'expOut';
  const tbl = el('div', 'exp-list');
  Object.keys(EXPANSIONS).sort().forEach((k) => {
    if (!EXPANSIONS[k]) return;
    const row = el('div', 'exp-row');
    row.append(el('code', null, '(' + k + ')'), el('span', 'exp-val', EXPANSIONS[k]));
    const x = el('button', 'icon-btn', '×'); x.type = 'button'; x.title = 'Remove ' + k; x.setAttribute('aria-label', 'Remove ' + k);
    x.onclick = () => { delete EXPANSIONS[k]; saveExpansions(EXPANSIONS); renderTypeBox(); };
    row.appendChild(x);
    tbl.appendChild(row);
  });
  items.appendChild(tbl);
  const add = el('div', 'row2');
  const kIn = el('input', 'field'); kIn.type = 'text'; kIn.placeholder = 'keyword'; kIn.setAttribute('aria-label', 'New keyword'); kIn.style.maxWidth = '140px';
  const vIn = el('input', 'field'); vIn.type = 'text'; vIn.placeholder = 'what it becomes'; vIn.setAttribute('aria-label', 'What the keyword becomes');
  const go = optBtn('Add', () => {
    const k = kIn.value.trim().toLowerCase().replace(/[^\w-]/g, '');
    if (!k || !vIn.value) { toast('Type a keyword and what it should become.'); return; }
    EXPANSIONS[k] = vIn.value; saveExpansions(EXPANSIONS); renderTypeBox();
  }, true);
  add.append(kIn, vIn, go);
  items.append(add, el('span', 'note', 'Keywords use letters, digits, hyphens and underscores. Removing a built-in one keeps it removed on this computer.'));
}

/* ---------------- expansions in every text box ----------------
   Typing (shrug) in a panel, a dialog or the canvas text editor turns it into the sign straight away. */
document.addEventListener('input', (e) => {
  const n = e.target;
  if (!n || !/INPUT|TEXTAREA/.test(n.tagName) || n.type === 'range' || n.type === 'checkbox' || n.type === 'color') return;
  if (n.dataset.noExpand === '1' || !hasExpansion(n.value)) return;
  const at = n.selectionStart, before = n.value;
  const after = expandText(before);
  if (after === before) return;
  n.value = after;
  const moved = after.length - before.length;
  try { n.setSelectionRange(at + moved, at + moved); } catch (err) { /* some inputs have no selection */ }
  n.dispatchEvent(new Event('input', { bubbles: false }));
}, true);

/* ===== 04c-wall.js ===== */
// SPDX-License-Identifier: AGPL-3.0-or-later

/* ---------------- the discovery wall ----------------
   Every style at once, drawn with the picture and the words you already have, so you can see what
   each one would do instead of trying them one by one. Picking a tile is the same as picking the
   style in the panel: the shared settings and the words come across. Tiles are drawn a few
   milliseconds at a time (sliceThumbs), so the window never blocks the main artwork. */
const wallState = { with: true, q: '' };
function wallStyles() {
  const q = wallState.q.trim().toLowerCase();
  const hit = ([k, m]) => !q || (m.name + ' ' + k + ' ' + (m.about || '')).toLowerCase().includes(q);
  const all = Object.entries(MODES).filter(hit);
  return { core: all.filter(([, m]) => !m.plugin), extra: all.filter(([, m]) => m.plugin) };
}
let wallJob = 0;
function openWall() {
  if (!src) return;
  closeMenus();
  const cur = curLayer();
  if (!cur) return;
  openDialog('Every style', (body, d) => {
    d.classList.add('wall-dlg');
    const top = el('div', 'wall-top');
    const find = el('input', 'field wall-find'); find.type = 'search'; find.placeholder = 'Find a style';
    find.setAttribute('aria-label', 'Find a style'); find.value = wallState.q;
    find.oninput = () => { wallState.q = find.value; draw(); };
    const other = activeLayers().filter((L) => L !== cur).length;
    top.appendChild(find);
    if (other) {
      const t = el('label', 'wall-with');
      const cb = el('input'); cb.type = 'checkbox'; cb.checked = wallState.with;
      cb.onchange = () => { wallState.with = cb.checked; draw(); };
      t.append(cb, el('span', null, 'Show the other text art layers too'));
      top.appendChild(t);
    }
    const grid = el('div', 'wall');
    const note = el('p', 'note', 'These are drawn from your picture and your words. Click one to use it. Your settings that every style shares, such as the color and the letters, come with you.');
    body.append(top, grid, note);

    // tiles take the shape of the artboard, kept between wide and a little tall, so the art fills its tile
    const g = artGeom(1), ar = clamp(g.TH / g.TW, 0.56, 1.25), cw = 240, chh = Math.round(cw * ar);
    const draw = () => {
      const job = ++wallJob;
      const { core, extra } = wallStyles();
      grid.replaceChildren();
      const shots = [];
      const add = (k, m) => {
        const b = el('button', 'wall-t' + (m.plugin ? ' plug' : '')); b.type = 'button';
        const on = cur.mode === k;
        b.setAttribute('aria-pressed', String(on));
        if (on) b.classList.add('on');
        const c = el('canvas'); c.width = cw; c.height = chh; c.style.aspectRatio = cw + ' / ' + chh; c.setAttribute('aria-hidden', 'true');
        const pic = el('div', 'wall-pic'); pic.appendChild(c);
        const name = el('span', 'wall-n', m.name);
        if (on) name.appendChild(el('small', null, 'in use now'));
        // styles that write along the Vector layer have nothing to draw until there are lines
        const needLines = (m.lines || m.usesLines) && !doc.lines.paths.length;
        if (needLines) {
          const nd = el('div', 'wall-need wall-lines');
          nd.innerHTML = '<svg viewBox="0 0 64 40" aria-hidden="true"><path d="M4 30C14 8 26 8 32 20s18 12 28-10" fill="none" stroke="currentColor" stroke-width="1.6" stroke-dasharray="3 2.4" stroke-linecap="round"/><path d="M4 36C18 22 30 30 42 26s14-6 18-8" fill="none" stroke="currentColor" stroke-width="1.6" stroke-dasharray="3 2.4" stroke-linecap="round" opacity=".55"/></svg>';
          nd.append(el('span', null, 'Writes along lines. There are none yet.'), el('span', 'wall-cta', 'Trace lines…'));
          pic.appendChild(nd);
        } else pic.classList.add('wait');
        b.append(pic, name);
        b.title = m.about || (m.plugin && m.plugin.description) || m.name;
        b.setAttribute('aria-label', (on ? 'Keep ' : 'Use ') + m.name);
        b.onclick = () => { closeDialog(); if (!on) setLayerStyle(k); };
        grid.appendChild(b);
        const v = on ? cur : layerInStyle(cur, k);
        if (!v || needLines) return;
        let list = [v];
        if (wallState.with) {
          list = activeLayers().map((x) => (x === cur ? v : x));
          if (!list.includes(v)) list = list.concat([v]);
        }
        // the whole picture fits in the tile, so nothing is cut off at the top or the sides
        shots.push(() => [c, sceneFor(list, 240 / doc.out.width, { coarse: 3.4 }), { contain: true }]);
      };
      core.forEach(([k, m]) => add(k, m));
      if (extra.length) {
        grid.appendChild(el('div', 'wall-h', 'Extra effects'));
        extra.forEach(([k, m]) => add(k, m));
      }
      if (!core.length && !extra.length) grid.appendChild(el('p', 'note', 'No style matches that. Try a shorter word.'));
      // longer slices than the panel thumbnails: the window is open to look at these, and the extra effects come last
      sliceThumbs(shots, () => job === wallJob && grid.isConnected, { slice: 14, rest: 4, done: (c, ok) => {
        const pic = c.parentNode; if (!pic) return;
        pic.classList.remove('wait');
        if (!ok) pic.appendChild(el('div', 'wall-need', 'This style could not be drawn here. Click to try it on the artboard.'));
      } });
    };
    draw();
  }, true);
}

/* ===== 05-plugins.js ===== */
/* ===================== Part 4b: plugins ===================== */
/* A plugin is a JavaScript file that calls Sungfluence.plugin({...}). The engine runs it as a style;
   this part turns its settings into panel controls, loads files the user picks, and remembers them. */
const PLUGIN_KEY = 'sungfluence-plugins-v1';
const builtinPlugins = new Set();
let pluginAdds = [];
const pluginErrShown = {};
function escapeHTML(s) { return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function pluginControl(c) {
  if (!c || typeof c !== 'object') return null;
  const lab = String(c.label || c.key || '').slice(0, 60);
  let o = null;
  if (c.type === 'range' && c.key) o = R(c.key, lab, +c.min || 0, +c.max || 1, +c.step || 0.01);
  else if (c.type === 'toggle' && c.key) o = T(c.key, lab);
  else if (['choice', 'seg', 'select'].includes(c.type) && c.key && Array.isArray(c.options)) {
    const opts = c.options.map((x) => (Array.isArray(x) ? [x[0], String(x[1] ?? x[0])] : [x, String(x)]));
    o = (opts.length <= 4 && c.type !== 'select') ? S(c.key, lab, opts) : SEL(c.key, lab, opts);
  } else if ((c.type === 'text' || c.type === 'textarea') && c.key) o = (c.type === 'text' ? TX : TA)(c.key, lab);
  else if (c.type === 'font') o = Object.assign({}, FONT);
  else if (c.type === 'color' || c.type === 'colormode') { const op = (c.options || ['ink', 'image', 'tone', 'duotone']).filter((x) => COLOR_LABEL[x] && x !== 'fill'); o = COL(op.length ? op : ['ink']); }
  else if (c.type === 'ink' && c.key) o = { key: c.key, label: lab, type: 'ink' };
  if (o) o.more = !!c.more;
  return o;
}
function addPluginMode(key, def) {
  const ctl = (Array.isArray(def.controls) ? def.controls : []).map(pluginControl).filter(Boolean);
  MODES[key] = {
    name: String(def.name || def.id).slice(0, 28), plugin: def, usesLines: !!def.usesLines,
    glyph: '<span class="pg">' + escapeHTML(String(def.icon || (def.name || def.id)[0]).slice(0, 3)) + '</span>',
    defaults: Object.assign({ color: 'ink' }, def.defaults || {}),
    controls: ctl.filter((c) => !c.more), more: ctl.filter((c) => c.more)
  };
}
function dropPluginMode(key) {
  delete MODES[key];
  let changed = false;
  doc.text.layers = doc.text.layers.map((L) => { if (L.mode !== key) return L; changed = true; return newLayer('rows', L.text ? { text: L.text } : {}); });
  if (changed) { buildPanel(); queueHistory(); scheduleText(0); }
}
C.plugins().forEach(({ key, def }) => { builtinPlugins.add(key); addPluginMode(key, def); });
C.onPlugin((ev, def, info) => {
  if (ev === 'add') { addPluginMode(info, def); pluginAdds.push(info); }
  else if (ev === 'remove') dropPluginMode(info);
  else if (ev === 'error') {
    const msg = String((info && info.message) || info).slice(0, 140);
    console.error('SungFluence plugin ' + def.id, info);
    if (!pluginErrShown[def.id + msg]) { pluginErrShown[def.id + msg] = 1; toast('The ' + (def.name || def.id) + ' plugin stopped: ' + msg); }
  }
});

/* Run a plugin file. Pages differ in what they allow, so try three ways in turn. */
function runPluginCode(code) {
  return new Promise((resolve, reject) => {
    pluginAdds = [];
    window.__sungfluencePlugin = { ran: false, error: null };
    const wrapped = 'window.__sungfluencePlugin.ran = true;\ntry {\n' + code + '\n;} catch (e) { window.__sungfluencePlugin.error = e; }';
    const settle = () => {
      const st = window.__sungfluencePlugin;
      if (!st.ran) return false;
      if (st.error) reject(st.error);
      else if (pluginAdds.length) resolve(pluginAdds.slice());
      else reject(new Error('The file ran but did not call Sungfluence.plugin({...}).'));
      return true;
    };
    // a page with its own security policy (the desktop app) allows only the third way
    const strict = !!document.querySelector('meta[http-equiv="Content-Security-Policy"]');
    if (!strict) {
      try { const s = document.createElement('script'); s.textContent = wrapped; document.head.appendChild(s); s.remove(); } catch (e) { /* inline scripts blocked */ }
      if (settle()) return;
      try { (0, Function)(wrapped)(); } catch (e) { /* eval blocked */ }
      if (settle()) return;
    }
    let url;
    try { url = URL.createObjectURL(new Blob([wrapped], { type: 'text/javascript' })); } catch (e) { reject(new Error('blocked')); return; }
    const s2 = document.createElement('script'); s2.src = url;
    s2.onload = () => { URL.revokeObjectURL(url); s2.remove(); if (!settle()) reject(new Error('blocked')); };
    s2.onerror = () => { URL.revokeObjectURL(url); s2.remove(); reject(new Error('blocked')); };
    document.head.appendChild(s2);
  });
}
function savedPlugins() { try { return JSON.parse(localStorage.getItem(PLUGIN_KEY) || '[]'); } catch (e) { return []; } }
function storePlugins(list) { try { localStorage.setItem(PLUGIN_KEY, JSON.stringify(list)); return true; } catch (e) { return false; } }
async function loadPluginText(code, fileName) {
  if (code.length > 600000) { toast('That plugin file is too large (600 KB at most).'); return; }
  try {
    const keys = await runPluginCode(code);
    const ids = keys.map((k) => k.slice(7));
    const list = savedPlugins().filter((p) => !p.ids.some((id) => ids.includes(id)));
    list.push({ file: fileName, ids, code });
    const kept = storePlugins(list);
    const names = keys.map((k) => MODES[k].name).join(', ');
    buildPanel(); if (!$('dlgScrim').hidden && $('dlgTitle') && $('dlgTitle').textContent === 'Plugins') openPlugins();
    toast('Added ' + names + '. Find it under Style, in Extra effects.' + (kept ? '' : ' It will be gone after a reload.'), { label: 'Use it', fn: () => usePluginStyle(keys[0]) });
  } catch (e) {
    const m = e && e.message === 'blocked'
      ? 'This page does not allow loading plugins. The desktop app does.'
      : 'Could not load the plugin: ' + String((e && e.message) || e).slice(0, 140);
    toast(m);
  }
}
const pluginInput = document.createElement('input');
pluginInput.type = 'file'; pluginInput.accept = '.js,.mjs,text/javascript'; pluginInput.hidden = true;
pluginInput.setAttribute('aria-hidden', 'true');
document.body.appendChild(pluginInput);
pluginInput.onchange = async () => {
  const f = pluginInput.files && pluginInput.files[0];
  pluginInput.value = '';
  if (f) await loadPluginText(await f.text(), f.name);
};
function removeUserPlugin(id) {
  storePlugins(savedPlugins().map((p) => Object.assign(p, { ids: p.ids.filter((x) => x !== id) })).filter((p) => p.ids.length));
  C.removePlugin(id);
  buildPanel(); if (!$('dlgScrim').hidden) openPlugins();
  toast('Plugin removed.');
}
function usePluginStyle(key) {
  if (!MODES[key]) return;
  // a style that writes along lines asks for lines first, as it does once text art is applied
  if (!doc.text.applied && (MODES[key].lines || MODES[key].usesLines) && !doc.lines.paths.length) { askForLines(key); return; }
  revealSoon();
  if (!doc.text.applied) {
    // the first look of Apply text art, in the style that was picked
    applyTextArt(key);
    return;
  }
  ui.tab = 'text'; buildTabs();
  setLayerStyle(key);
  if (ui.view === 'photo') setView('text');
}
/* The Plugins window: opened from the Plugins button at the top, the desktop menu bar, or "Plugins…" next to Extra effects */
function openPlugins() {
  openDialog('Plugins', (body) => {
    body.appendChild(el('p', 'note', 'A plugin is a small JavaScript file that adds an effect. Its effects appear under Style, in Extra effects. Plugins run code inside SungFluence, so only load files you trust.'));
    const list = el('div', 'plugin-list');
    C.plugins().forEach(({ key, def }) => {
      const row = el('div', 'plugin-row');
      const info = el('div', 'pi');
      const meta = [def.version ? 'v' + def.version : '', def.author || '', builtinPlugins.has(key) ? 'comes with SungFluence' : 'loaded by you'].filter(Boolean).join(' · ');
      info.append(el('b', null, String(def.name || def.id)), el('small', null, meta));
      if (def.description) info.appendChild(el('span', 'note', String(def.description).slice(0, 200)));
      row.appendChild(info);
      const acts = el('div', 'pa');
      const use = el('button', 'mini-btn', 'Use'); use.type = 'button'; use.onclick = () => { closeDialog(); usePluginStyle(key); };
      acts.appendChild(use);
      if (!builtinPlugins.has(key)) { const rm = el('button', 'mini-btn', 'Remove'); rm.type = 'button'; rm.onclick = () => removeUserPlugin(def.id); acts.appendChild(rm); }
      row.appendChild(acts);
      list.appendChild(row);
    });
    body.appendChild(list);
    const g = el('div', 'grid2');
    g.append(optBtn('Load plugin…', () => pluginInput.click(), true), optBtn('Get the template', () => saveFile('sungfluence-plugin-template.js', PLUGIN_FILES['sungfluence-plugin-template.js'])));
    body.appendChild(g);
    body.appendChild(el('p', 'note', 'To make your own, get the template, change it in any text editor, and load it here. The guide is docs/PLUGINS.md in the source code.'));
  });
}
$('pluginsBtn').onclick = openPlugins;
/* plugins the user loaded before come back on start */
const pluginsReady = (async () => {
  for (const p of savedPlugins()) {
    try { await runPluginCode(p.code); } catch (e) { console.warn('Saved plugin did not load', p.file, e); }
  }
})();

/* ===== 05b-help.js ===== */
/* ===================== Part 4c: help ===================== */
/* The Help window shows the pages from docs/help, which the build bundles into HELP (src/help.js),
   so help works offline. Links to other help pages open here; other links open in the browser. */
const helpState = { page: 'index' };
function openHelp(page, anchor) {
  if (typeof HELP === 'undefined' || !HELP.order.length) { toast('Help is not included in this copy of SungFluence.'); return; }
  helpState.page = HELP.pages[page] ? page : helpState.page;
  openDialog('Help', (body, d) => {
    d.classList.add('help-dlg');
    const box = el('div', 'help-wrap');
    const nav = el('nav', 'help-nav'); nav.setAttribute('aria-label', 'Help topics');
    const search = el('input', 'field'); search.type = 'search'; search.placeholder = 'Search help'; search.setAttribute('aria-label', 'Search help');
    const list = el('div', 'help-list');
    const content = el('article', 'help-content'); content.tabIndex = -1;
    nav.append(search, list);
    box.append(nav, content);
    body.appendChild(box);
    const show = (id, anchorId) => {
      if (!HELP.pages[id]) return;
      helpState.page = id;
      content.innerHTML = HELP.pages[id].html;
      list.querySelectorAll('button').forEach((b) => b.setAttribute('aria-current', String(b.dataset.id === id)));
      const target = anchorId && content.querySelector('#' + CSS.escape(anchorId));
      if (target) target.scrollIntoView(); else content.scrollTop = 0;
    };
    const renderList = (q) => {
      list.replaceChildren();
      HELP.order.forEach((id) => {
        const P = HELP.pages[id];
        if (q && !P.text.includes(q) && !P.title.toLowerCase().includes(q)) return;
        const b = el('button', 'help-item', P.title); b.type = 'button'; b.dataset.id = id;
        b.setAttribute('aria-current', String(id === helpState.page));
        b.onclick = () => show(id);
        list.appendChild(b);
      });
      if (!list.children.length) list.appendChild(el('span', 'note', 'Nothing found.'));
    };
    search.oninput = () => {
      const q = search.value.trim().toLowerCase();
      renderList(q);
      // jump to the first page that has it
      const first = list.querySelector('button');
      if (q && first && first.dataset.id !== helpState.page && !HELP.pages[helpState.page].text.includes(q)) show(first.dataset.id);
    };
    content.addEventListener('click', (e) => {
      const a = e.target.closest('a');
      if (!a) return;
      const href = a.getAttribute('href') || '';
      if (href.startsWith('#help:')) { e.preventDefault(); const [pg, an] = href.slice(6).split('#'); show(pg || helpState.page, an); return; }
      if (href.startsWith('#')) { e.preventDefault(); const t = content.querySelector(href); if (t) t.scrollIntoView(); return; }
      a.target = '_blank'; a.rel = 'noopener';
    });
    renderList('');
    show(helpState.page, anchor);
  }, true);
}
/* A first visit gets one gentle pointer to the tutorial, never again after that */
function welcomeOnce() {
  if (prefs.welcomed) return;
  // the card that offers the first look comes first; the hint follows once it is answered
  const cta = document.getElementById('cta');
  if (cta && !cta.hidden) { ui.welcomeLater = true; return; }
  ui.welcomeLater = false;
  // a toast that offers a next step, such as the Word cloud after a first look in another style, is not replaced
  if (toastBusy()) { setTimeout(welcomeOnce, 1500); return; }
  prefs.welcomed = true; savePrefs();
  toast('New to SungFluence? The getting started guide takes five minutes.', { label: 'Open it', fn: () => openHelp('getting-started') });
}

/* ===== 05c-commands.js ===== */
/* ===================== Part 4d: commands, menus and the command palette ===================== */
/* Every action is a command: an id, a label, its keys, and one function. The menu bar (in the page on the web,
   the native one in the desktop app), the command palette (Ctrl K), keyboard shortcuts and tests all use this list.
   keys: 'mod' is Ctrl (Cmd on a Mac). The first entry is shown in menus; all of them work. */
const COMMANDS = new Map();
function command(id, label, run, o) {
  COMMANDS.set(id, Object.assign({ id, label, run, keys: [] }, o || {}));
  return { id };
}
function runCommand(id) {
  const c = COMMANDS.get(id);
  if (!c) return false;
  if (c.enabled && !c.enabled()) return false;
  closeMenus();
  c.run();
  syncMenus();
  return true;
}
const hasImg = () => !!origImg;
