MIRROR_WRITING.forEach(([v, t]) => command('type.mirror.' + v, 'Mirror the writing: ' + t, () => setMirrorWriting(v), { checked: () => (curLayer().mirror || 'none') === v, enabled: hasImg }));
command('image.canvas', 'Canvas size…', () => openCanvasSize(), { enabled: hasImg });
