    const p = C.parseColor(c), q = C.rgbToCmyk(p[0], p[1], p[2]), t = Math.max(0, (q[3] - 0.5) / 0.5);
    if (t > 0) { q[0] = Math.max(q[0], 0.6 * t); q[1] = Math.max(q[1], 0.4 * t); q[2] = Math.max(q[2], 0.4 * t); }
